-- Users. Column names and sizes follow the SDK table reference.
CREATE TABLE "OUSR" (
    "USERID"    INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "USER_CODE" VARCHAR(25)  NOT NULL UNIQUE,
    "U_NAME"    VARCHAR(155),
    "PASSWORD"  VARCHAR(254) NOT NULL,
    "SUPERUSER" VARCHAR(1)   NOT NULL DEFAULT 'N' CHECK ("SUPERUSER" IN ('Y', 'N')),
    "Locked"    VARCHAR(1)   NOT NULL DEFAULT 'N' CHECK ("Locked" IN ('Y', 'N'))
);
